import type { FetchFunction } from '@earendil-works/pi-ai';

/**
 * Provider SDKs generated by Stainless (Anthropic, OpenAI, …) attach telemetry
 * headers such as `x-stainless-os`. Gateways and CORS proxies often do not list
 * them in `Access-Control-Allow-Headers`, which makes the browser's preflight
 * fail even with a valid key — e.g. the Vercel AI Gateway rejects
 * `x-stainless-os`. ReAgent runs in the browser, so strip those headers before
 * the request leaves the page.
 *
 * Only `x-stainless-*` is removed; auth and API-version headers are untouched.
 */
function stripTelemetryHeaders(headers: HeadersInit | undefined): HeadersInit | undefined {
  if (headers === undefined) {
    return undefined;
  }
  const next = new Headers(headers);
  for (const name of [...next.keys()]) {
    if (name.toLowerCase().startsWith('x-stainless-')) {
      next.delete(name);
    }
  }
  return next;
}

/** Wrap a fetch implementation so telemetry headers never reach the network. */
export function browserSafeFetch(base?: FetchFunction): FetchFunction {
  const impl = base ?? fetch;
  return (input, init) =>
    impl(
      input,
      init === undefined ? init : { ...init, headers: stripTelemetryHeaders(init.headers) },
    );
}
